E1.css:
[data-ui-unit="E1"].trip-header {
  display: flex;
  align-items: center;
  min-height: 62px;
}

[data-ui-unit="E1"].trip-header > button,
[data-ui-unit="E1"].trip-header > span {
  flex: 0 0 44px;
  display: flex;
  align-items: center;
  justify-content: center;
}

[data-ui-unit="E1"].trip-header > h1 {
  flex: 1 1 auto;
  min-width: 0;
  text-align: center;
  font-size: 18px;
  line-height: 26px;
  font-weight: 700;
  margin: 0;
  overflow-wrap: break-word;
}

[data-ui-unit="E1"].trip-header button {
  background: transparent;
  border: none;
  padding: 0;
  width: 44px;
  height: 44px;
  cursor: default;
}

[data-ui-unit="E1"].trip-header button img {
  width: 24px;
  height: 24px;
  display: block;
}

[data-ui-unit="E1"].trip-header button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

E2.css:
[data-ui-unit="E2"].day-tabs {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 8px;
}

[data-ui-unit="E2"].day-tabs button {
  font: 700 14px/1 "Noto Sans KR", sans-serif;
  padding: 8px 16px;
  min-width: 64px;
  min-height: 32px;
  height: auto;
  border-radius: 16px;
  border: 1px solid #e8e8e8;
  background-color: #fff;
  color: #111;
  cursor: default;
  white-space: nowrap;
  margin: 0;
}

[data-ui-unit="E2"].day-tabs button[aria-pressed="true"] {
  background-color: #111;
  color: #fff;
  border-color: #111;
}

[data-ui-unit="E2"].day-tabs button:disabled {
  opacity: 1;
}
